interface Utilizador {
  id: number;
  nome: string;
  telefone?: string; // o tipo lido é string | undefined
}

// Com a propriedade e sem ela: as duas formas são válidas
const completo: Utilizador = { id: 1, nome: "Ana", telefone: "912345678" };
const minimo: Utilizador = { id: 2, nome: "Bruno" };

// @ts-expect-error id e nome continuam obrigatórios
const invalido: Utilizador = { telefone: "912345678" };

// @ts-expect-error telefone pode ser undefined: não se lê .length às cegas
const tamanho = minimo.telefone.length;

// As saídas habituais
const seguro = minimo.telefone?.length ?? 0; // 0
const comOmissao = minimo.telefone ?? "sem telefone"; // "sem telefone"

function formatar(u: Utilizador): string {
  if (u.telefone === undefined) {
    return u.nome;
  }
  // a partir daqui u.telefone é string
  return `${u.nome} (${u.telefone.trim()})`;
}

console.log(completo, invalido, tamanho, seguro, comOmissao);
console.log(formatar(minimo)); // "Bruno"

interface ComOpcional {
  nome?: string;
}

interface ComUndefined {
  nome: string | undefined;
}

// A opcional pode simplesmente faltar
const a: ComOpcional = {};

// @ts-expect-error a obrigatória tem de estar presente, nem que seja com undefined
const b: ComUndefined = {};
const c: ComUndefined = { nome: undefined };

// Ao ler, o tipo é o mesmo nos dois casos
const x: string | undefined = a.nome;
const y: string | undefined = c.nome;

// A diferença está na presença da chave
console.log(Object.keys(a).length); // 0
console.log(Object.keys(c).length); // 1
console.log("nome" in a); // false
console.log("nome" in c); // true

// Sem exactOptionalPropertyTypes, uma opcional aceita undefined explícito
const d: ComOpcional = { nome: undefined }; // aceite por omissão
// Com exactOptionalPropertyTypes ligada, a linha acima passa a ser erro:
// o tipo de nome é string, e não string | undefined.
// Para a continuar a permitir, declarava-se nome?: string | undefined

console.log(b, x, y, d);

interface Config {
  readonly url: string;
  readonly porta: number;
  timeout: number;
}

const config: Config = {
  url: "https://api.exemplo.pt",
  porta: 443,
  timeout: 5000,
};

config.timeout = 10000; // permitido: não é readonly

// @ts-expect-error url é readonly e não pode ser reatribuída
config.url = "http://outra.pt";

// readonly protege a propriedade; const protege a variável
// @ts-expect-error config foi declarado com const
config = { url: "x", porta: 80, timeout: 1 };

// O padrão habitual: em vez de alterar, devolver um objeto novo
type Ponto = { readonly x: number; readonly y: number };

function mover(p: Ponto, dx: number, dy: number): Ponto {
  return { x: p.x + dx, y: p.y + dy };
}

const origem: Ponto = { x: 0, y: 0 };
console.log(mover(origem, 3, 4)); // { x: 3, y: 4 }

// readonly não impede a atribuição inicial nem a criação por spread
const copia: Ponto = { ...origem, x: 10 };
console.log(config.timeout, copia); // 10000 { x: 10, y: 0 }

interface Perfil {
  readonly nome: string;
  readonly morada: { rua: string; cidade: string };
  readonly etiquetas: string[];
}

const perfil: Perfil = {
  nome: "Ana",
  morada: { rua: "Rua A", cidade: "Porto" },
  etiquetas: ["admin"],
};

// @ts-expect-error a propriedade morada está protegida
perfil.morada = { rua: "Rua B", cidade: "Braga" };

// O interior do objeto aninhado não está: readonly é raso
perfil.morada.cidade = "Braga"; // compila sem uma queixa
perfil.etiquetas.push("editor"); // idem

console.log(perfil.morada.cidade); // "Braga"
console.log(perfil.etiquetas); // ["admin", "editor"]

// E desaparece na compilação: o JavaScript emitido não sabe o que é readonly
const comoObjetoQualquer = perfil as { nome: string };
comoObjetoQualquer.nome = "Bruno";
console.log(perfil.nome); // "Bruno"

// A proteção em tempo de execução tem outro nome
const congelado = Object.freeze({ id: 1, total: 10 });
// @ts-expect-error Object.freeze devolve um tipo Readonly
congelado.total = 20; // em modo estrito lança TypeError; sem ele, é ignorada
console.log(congelado.total); // 10, o objeto está mesmo protegido

// Chaves desconhecidas de antemão, todos os valores do mesmo tipo
interface Traducoes {
  [chave: string]: string;
}

const pt: Traducoes = { hello: "olá", bye: "adeus" };
pt.thanks = "obrigado";
pt["please"] = "por favor";

// @ts-expect-error o valor tem de ser compatível com o tipo do índice
pt.idade = 42;

// O acesso devolve sempre o tipo declarado, mesmo para chaves que não existem
const nada = pt["inexistente"]; // tipo string; em execução, undefined

// Também se escreve com type alias, e o valor pode ser qualquer tipo
type Stock = { [referencia: string]: number };
const stock: Stock = { "ABC-1": 10 };
stock["XYZ-9"] = 4;

// readonly aplica-se à própria index signature
type Tabela = { readonly [chave: string]: number };
const tabela: Tabela = { a: 1 };
// @ts-expect-error a index signature só permite leitura
tabela.a = 2;

console.log(pt, nada, stock, tabela); // nada é undefined

// Propriedades conhecidas ao lado de uma index signature
interface Resposta {
  estado: number;
  mensagem: string;
  [cabecalho: string]: string | number;
}

const r: Resposta = {
  estado: 200,
  mensagem: "OK",
  "x-request-id": "abc-123",
};
console.log(r.estado, r["x-request-id"]); // 200 "abc-123"

// A regra: cada propriedade declarada tem de caber no tipo do índice
interface Invalida {
  // @ts-expect-error boolean não cabe na index signature de string
  ativo: boolean;
  [chave: string]: string;
}

// Índice numérico: as chaves são números, não strings
interface Linhas {
  [indice: number]: string;
}
const linhas: Linhas = { 0: "primeira", 1: "segunda" };
console.log(linhas[0]); // "primeira"

// Os dois índices podem coexistir, mas o numérico tem de caber no de string,
// porque em JavaScript obj[0] e obj["0"] são a mesma chave
interface Misto {
  [chave: string]: string | number;
  [indice: number]: number;
}
const misto: Misto = { titulo: "relatório", 0: 10 };
console.log(misto[0], misto["titulo"]); // 10 "relatório"

interface Conflito {
  [chave: string]: number;
  // @ts-expect-error o índice numérico tem de ser compatível com o de string
  [indice: number]: string;
}

const conflito: Conflito = {};
console.log(conflito);

type Precos = { [artigo: string]: number };

const precos: Precos = { cafe: 0.8, agua: 0.6 };

// Sem noUncheckedIndexedAccess, o tipo declarado é number e isto compila
const cha = precos["cha"]; // tipo number; valor real: undefined
try {
  console.log(cha.toFixed(2)); // TypeError em tempo de execução
} catch (erro) {
  console.log((erro as TypeError).message); // "Cannot read properties of undefined..."
}

// Com noUncheckedIndexedAccess ligada, precos["cha"] passa a ser
// number | undefined e a linha acima deixa de compilar

// A defesa que funciona com ou sem a opção: anotar o que é verdade
const talvez: number | undefined = precos["cha"];
if (talvez !== undefined) {
  console.log(talvez.toFixed(2));
}

// Ou usar os operadores que já conhece
console.log(precos["cha"] ?? 0); // 0

// A opção não afeta as propriedades declaradas explicitamente
interface Carrinho {
  total: number;
  [artigo: string]: number;
}
const carrinho: Carrinho = { total: 1.4, cafe: 0.8 };
console.log(carrinho.total.toFixed(2)); // "1.40", seguro em qualquer caso

