interface Livro {
  readonly isbn: string;
  titulo: string;
  autor: string;
  ano?: number;
  editora?: string;
}

const minimo: Livro = { isbn: "978-989-1", titulo: "Ensaio", autor: "Ana" };
const completo: Livro = {
  isbn: "978-989-2",
  titulo: "Rede",
  autor: "Bruno",
  ano: 2020,
  editora: "Norte",
};

// @ts-expect-error o isbn é readonly e não pode mudar depois de criado
minimo.isbn = "978-989-9";

minimo.titulo = "Ensaio revisto"; // permitido: titulo não é readonly

function descrever(livro: Livro): string {
  const ano = livro.ano === undefined ? "sem data" : String(livro.ano);
  const editora = livro.editora ?? "editora desconhecida";
  return `${livro.titulo}, ${livro.autor} (${ano}, ${editora})`;
}

console.log(descrever(minimo)); // "Ensaio revisto, Ana (sem data, editora desconhecida)"
console.log(descrever(completo)); // "Rede, Bruno (2020, Norte)"

interface Preferencias {
  idioma?: string;
  notificacoes: boolean | undefined;
}

// @ts-expect-error notificacoes é obrigatória, mesmo aceitando undefined
const emFalta: Preferencias = {};

const semIdioma: Preferencias = { notificacoes: undefined };
const comIdiomaIndefinido: Preferencias = {
  idioma: undefined,
  notificacoes: true,
};

function foiDecidido(p: Preferencias, chave: keyof Preferencias): boolean {
  return chave in p;
}

console.log(foiDecidido(semIdioma, "idioma")); // false
console.log(foiDecidido(comIdiomaIndefinido, "idioma")); // true
console.log(foiDecidido(semIdioma, "notificacoes")); // true

function resumir(p: Preferencias): string {
  const idioma = p.idioma ?? "pt";
  const notificacoes = p.notificacoes ?? false;
  return `${idioma}/${notificacoes}`;
}

console.log(resumir(semIdioma)); // "pt/false"
console.log(resumir(comIdiomaIndefinido)); // "pt/true"
console.log(emFalta);

type Contagem = { [palavra: string]: number };

function contar(palavras: readonly string[]): Contagem {
  const resultado: Contagem = {};
  for (const palavra of palavras) {
    const chave = palavra.toLowerCase();
    const atual: number | undefined = resultado[chave];
    resultado[chave] = (atual ?? 0) + 1;
  }
  return resultado;
}

function vezes(contagem: Contagem, palavra: string): number {
  const valor: number | undefined = contagem[palavra.toLowerCase()];
  return valor ?? 0;
}

const contagem = contar(["Sim", "não", "sim", "Talvez", "SIM"]);

console.log(contagem); // { sim: 3, "não": 1, talvez: 1 }
console.log(vezes(contagem, "SIM")); // 3
console.log(vezes(contagem, "nunca")); // 0

// @ts-expect-error a index signature obriga a valores do tipo number
contagem.sim = "três";

interface RespostaHttp {
  readonly estado: number;
  readonly duracaoMs?: number;
  readonly [cabecalho: string]: string | number | undefined;
}

const resposta: RespostaHttp = {
  estado: 200,
  duracaoMs: 34,
  "content-type": "application/json",
  "x-cache": "HIT",
};

// @ts-expect-error a index signature é readonly: nada se escreve depois
resposta["content-type"] = "text/html";

// @ts-expect-error estado é readonly
resposta.estado = 500;

function cabecalho(r: RespostaHttp, nome: string): string | undefined {
  const valor = r[nome.toLowerCase()]; // string | number | undefined
  return typeof valor === "string" ? valor : undefined;
}

function descrever(r: RespostaHttp): string {
  const tipo = cabecalho(r, "Content-Type") ?? "desconhecido";
  const duracao = r.duracaoMs === undefined ? "?" : `${r.duracaoMs}ms`;
  return `${r.estado} ${tipo} em ${duracao}`;
}

console.log(descrever(resposta)); // "200 application/json em 34ms"
console.log(cabecalho(resposta, "x-nao-existe")); // undefined
console.log(descrever({ estado: 404 })); // "404 desconhecido em ?"
